def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    # Keep only separator lines whose color is shared by a row and column.
    row_lines = [r for r in sep_rows if grid[r][0] in {grid[0][c] for c in sep_cols}]
    col_lines = [c for c in sep_cols if grid[0][c] in {grid[r][0] for r in sep_rows}]

    row_bounds = [-1] + row_lines + [h]
    col_bounds = [-1] + col_lines + [w]
    panels = []
    for ri in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[ri] + 1, row_bounds[ri + 1]
        for ci in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[ci] + 1, col_bounds[ci + 1]
            panels.append((r0, r1, c0, c1))

    # Identify the background as the most frequent non-separator color.
    separator_colors = {grid[r][0] for r in row_lines} | {grid[0][c] for c in col_lines}
    counts = {}
    for row in grid:
        for value in row:
            if value not in separator_colors:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    source = None
    for r0, r1, c0, c1 in panels:
        cells = [(r - r0, c - c0, grid[r][c])
                 for r in range(r0, r1) for c in range(c0, c1)
                 if grid[r][c] != background]
        if cells:
            source = cells
            break

    out = [row[:] for row in grid]
    if source is None:
        return out
    for r0, r1, c0, c1 in panels:
        for dr, dc, value in source:
            if r0 + dr < r1 and c0 + dc < c1:
                out[r0 + dr][c0 + dc] = value
    return out
